 \E_{(\line_X, x) \sim D_{\tvar, i}}  \sum_{a} \bra{\hat{\psi}}  \hat{M}^{(\Line,\xpt),\line_\xpt}_{[\eval_x(\cdot)=a]} \ot \hat{M}^{(\Point,X),x}_{a} \ket{\hat{\psi}}\;, 
