\begin{claim}\label{claim:17-3}
\begin{align}
  \E_{(\line, \line_X, \line_Z) \sim D}\E_{(x,z,\alpha, \beta) \in \line}\sum_{f_X,f_Z} \bra{\hat{\psi}} T^{\line_X, \line_Z}_{f_X, f_Z} \ot  \hat{M}^{(\Point,Z),z}_{f_Z(z)} \ket{\hat{\psi}} 
