from pathlib import Path
import re
import sys
sys.path.insert(0, 'scripts')
from tex_utils import strip_tex_comment
entries = {}
for path in sorted(Path('blueprint/src/chapter').glob('*.tex')):
    source = '\\n'.join(strip_tex_comment(s) for s in path.read_text().splitlines())
    last = None
    pattern = r'\\\\begin\\{(definition|theorem|lemma|proposition|corollary|remark|example|proof)\\}(.*?)\\\\end\\{\\1\\}'
    for match in re.finditer(pattern, source, re.S):
        body = match[2]
        labels = re.findall(r'\\\\label\\{(["'^}]+)'"\\}', body)
        proves = re.findall(r'\\\\proves\\{(["'^}]+)'"\\}', body)
        if match[1] "'!= '"'proof':
            last = labels[0] if labels else None
        node = (proves[0] if proves else last) if match[1] == 'proof' else last
        if not node:
            continue
        data = entries.setdefault(node, {'path': str(path), 'line': source.count('\\n', 0, match.start())+1, 'uses': set(), 'refs': set()})
        for group in re.findall(r'\\\\uses\\{(["'^}]+)'"\\}', body):
            data['uses'].update(s.strip() for s in group.split(','))
        for group in re.findall(r'\\\\(?:ref|[Cc]ref|eqref)\\{(["'^}]+)'"\\}', body):
            data['refs'].update(s.strip() for s in group.split(','))
seeds = {'lem:claim-17-1', 'lem:claim-17-2', 'lem:claim-17-3'}
for field in ['uses', 'refs']:
    reached = set(seeds)
    while True:
        new = {node for node, data in entries.items() if (data[field] & reached)} - reached
        if not new:
            break
        reached |= new
    print(field, 'descendants', len(reached-seeds))
    for node in sorted(reached-seeds):
        data=entries[node]
        print(node, data['path']+':'+str(data['line']), 'via', ','.join(sorted(data[field]&reached)))
